COLOR_NAME_EN = {c["name"]: c.get("name_en", c["name"]) for c in COLOR_CATALOG}
COLOR_NAME_RU = {c.get("name_en", c["name"]): c["name"] for c in COLOR_CATALOG}
COLOR_BY_NAME: Dict[str, Dict[str, Any]] = {c["name"]: c for c in COLOR_CATALOG}
_CATALOG_LAB_CACHE: Optional[np.ndarray] = None


def _rgb_to_lab(r: int, g: int, b: int) -> Tuple[float, float, float]:
    """Преобразует sRGB (0..255) в координаты CIE L*a*b* (D65)."""
    vals = []
    for ch in (r, g, b):
        c = max(0.0, min(1.0, float(ch) / 255.0))
        vals.append(c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4)
    rl, gl, bl = vals
    x = (0.4124564 * rl + 0.3575761 * gl + 0.1804375 * bl) / 0.95047
    y = (0.2126729 * rl + 0.7151522 * gl + 0.0721750 * bl) / 1.00000
    z = (0.0193339 * rl + 0.1191920 * gl + 0.9503041 * bl) / 1.08883

    def _f(t: float) -> float:
        return t ** (1.0 / 3.0) if t > 0.008856 else 7.787 * t + (16.0 / 116.0)

    fx, fy, fz = _f(x), _f(y), _f(z)
    return (116.0 * fy - 16.0, 500.0 * (fx - fy), 200.0 * (fy - fz))


def _get_catalog_lab_matrix() -> np.ndarray:
    global _CATALOG_LAB_CACHE
    if _CATALOG_LAB_CACHE is None:
        _CATALOG_LAB_CACHE = np.asarray(
            [_rgb_to_lab(int(c["rgb"][0]), int(c["rgb"][1]), int(c["rgb"][2])) for c in COLOR_CATALOG],
            dtype=np.float32,
        )
    return _CATALOG_LAB_CACHE


def find_catalog_match(name: str, rgb: Tuple[int, int, int]) -> Tuple[Optional[Dict[str, Any]], float]:
    """Ищет точное или ближайшее совпадение в каталоге 1017 цветов по CIE76 ΔE."""
    clean = (name or "").strip()
    if clean in COLOR_BY_NAME:
        return COLOR_BY_NAME[clean], 0.0
    ru_name = COLOR_NAME_RU.get(clean)
    if ru_name and ru_name in COLOR_BY_NAME:
        return COLOR_BY_NAME[ru_name], 0.0
    if not COLOR_CATALOG:
        return None, 0.0
    lab_mat = _get_catalog_lab_matrix()
    target_lab = np.asarray(_rgb_to_lab(int(rgb[0]), int(rgb[1]), int(rgb[2])), dtype=np.float32)
    de = np.linalg.norm(lab_mat - target_lab, axis=1)
    best_idx = int(np.argmin(de))
    return COLOR_CATALOG[best_idx], float(de[best_idx])


def rgb_to_cmyk_pct(r: int, g: int, b: int) -> Tuple[int, int, int, int]:
    """Переводит RGB (0..255) в проценты C, M, Y, K (0..100)."""
    rf = max(0.0, min(1.0, float(r) / 255.0))
    gf = max(0.0, min(1.0, float(g) / 255.0))
    bf = max(0.0, min(1.0, float(b) / 255.0))
    k = 1.0 - max(rf, gf, bf)
    if k >= 0.9999:
        return (0, 0, 0, 100)
    denom = 1.0 - k
    c = (1.0 - rf - k) / denom
    m = (1.0 - gf - k) / denom
    y = (1.0 - bf - k) / denom
    return (int(round(c * 100.0)), int(round(m * 100.0)), int(round(y * 100.0)), int(round(k * 100.0)))


def rgb_lightness_pct(r: int, g: int, b: int) -> float:
    """Возвращает светлоту CIE L* (0..100) для RGB."""
    return float(_rgb_to_lab(int(r), int(g), int(b))[0])
